      "category": "network_architecture",
      "rationale": "Expand each SASRec feed-forward intermediate dimension to four times the hidden dimension across all four datasets. This increases nonlinear capacity while preserving attention depth, heads, activation, residual paths, embeddings, scoring, loss and optimizer. Record the expansion in checkpoint metadata and use it in the generated predictor.",
      "edits": [
        {
          "find": "NUM_EPOCHS   = int(os.environ.get(\"SASREC_EPOCHS\",    \"300\"))",
          "replace": "NUM_EPOCHS   = min(200, int(os.environ.get(\"SASREC_EPOCHS\", \"200\")))"
        },
        {
          "find": "DATA_DIR = os.environ.get(\"GAGC_DATA_DIR\", \"./input/trainval\")",
          "replace": "DATA_DIR = os.environ['GAGC_DATA_DIR']"
        },
        {
          "find": "class PointWiseFeedForward(nn.Module):\n    def __init__(self, hidden_units: int, dropout_rate: float):\n        super().__init__()\n        self.conv1 = nn.Conv1d(hidden_units, hidden_units, kernel_size=1)\n        self.dropout1 = nn.Dropout(dropout_rate)\n        self.relu = nn.ReLU()\n        self.conv2 = nn.Conv1d(hidden_units, hidden_units, kernel_size=1)",
          "replace": "class PointWiseFeedForward(nn.Module):\n    def __init__(self, hidden_units: int, dropout_rate: float, ffn_multiplier: int = 4):\n        super().__init__()\n        intermediate_units = hidden_units * ffn_multiplier\n        self.conv1 = nn.Conv1d(hidden_units, intermediate_units, kernel_size=1)\n        self.dropout1 = nn.Dropout(dropout_rate)\n        self.relu = nn.ReLU()\n        self.conv2 = nn.Conv1d(intermediate_units, hidden_units, kernel_size=1)"
        },
        {
          "find": "class SASRec(nn.Module):\n    def __init__(self, itemnum: int, hidden_units: int = 64, num_blocks: int = 2,\n                 num_heads: int = 1, dropout_rate: float = 0.5, maxlen: int = 128):",
