        },
        {
          "find": "self.forward_layers.append(PointWiseFeedForward(hidden_units, dropout_rate))",
          "replace": "self.forward_layers.append(PointWiseFeedForward(hidden_units, dropout_rate, ffn_multiplier))"
        },
