          "find": "        dropout_rate=DROPOUT_RATE,\n        maxlen=MAXLEN,\n    ).to(device)",
          "replace": "        dropout_rate=DROPOUT_RATE,\n        maxlen=MAXLEN,\n        ffn_multiplier=4,\n    ).to(device)"
        },
        {
          "find": "            \"dropout_rate\": DROPOUT_RATE,\n            \"maxlen\": MAXLEN,\n        }, f)",
          "replace": "            \"dropout_rate\": DROPOUT_RATE,\n            \"maxlen\": MAXLEN,\n            \"ffn_multiplier\": 4,\n        }, f)"
        },
        {
          "find": "            dropout_rate=0.0,\n            maxlen=meta[\"maxlen\"],\n        ).to(_device)",
          "replace": "            dropout_rate=0.0,\n            maxlen=meta[\"maxlen\"],\n            ffn_multiplier=meta[\"ffn_multiplier\"],\n        ).to(_device)"
        }
      ]
    }
